# Prueba en Chromium con un Circuit Tracks SIMULADO (Web MIDI falso) y audio falso de Chrome.
import re
# No valida hardware real ni el sonido de los patches.
import sys, os, glob, json, threading, http.server, functools
from playwright.sync_api import sync_playwright
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
OUT = os.path.join(ROOT, 'tests', 'out'); SHOTS = os.path.join(ROOT, 'tests', 'shots'); os.makedirs(SHOTS, exist_ok=True)
H = functools.partial(http.server.SimpleHTTPRequestHandler, directory=os.path.join(ROOT, 'dist'))
class Q(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *a): pass
srv = http.server.ThreadingHTTPServer(('127.0.0.1', 8771), functools.partial(Q, directory=os.path.join(ROOT, 'dist'))); threading.Thread(target=srv.serve_forever, daemon=True).start()
URL = 'http://127.0.0.1:8771/Circuit_Tracks_Patch_Library_Editor.html'
FAKE_MIDI = """(() => {
  const sent = []; window.__midiSent = sent; const listeners = []; const cur = [null, null];
  const mk = (i) => { const b = new Array(340).fill(0); const nm = ('Device P' + (i + 1)).padEnd(16, ' '); for (let k = 0; k < 16; k++) b[k] = nm.charCodeAt(k);
    Object.assign(b, { 32: 2, 34: 64, 35: 64, 36: 2, 37: 127, 38: 64, 42: 64, 43: 64, 44: 76, 45: 2, 46: 127, 47: 64, 51: 64, 52: 64, 53: 76, 54: 127, 58: 64, 59: 64, 63: 1, 64: (i * 2) % 128, 65: 127, 67: 64, 68: 64, 69: 64, 70: 2, 71: 90, 72: 127, 73: 40, 74: 64, 75: 2, 76: 75, 77: 35, 78: 45, 80: 10, 81: 70, 82: 64, 83: 40, 89: 68, 97: 68, 105: 64, 106: 64, 107: 64, 108: 64, 109: 125, 110: 64, 117: 100, 118: 1, 119: 20, 121: 74, 122: 64, 123: 64 });
    for (let j = 0; j < 20; j++) b[126 + 4 * j] = 64; for (let k = 0; k < 8; k++) for (let j = 0; j < 4; j++) { b[207 + 17 * k + 4 * j] = 127; b[208 + 17 * k + 4 * j] = 64; } return b; };
  const bank = Array.from({ length: 64 }, (_, i) => mk(i));
  const input = { id: 'in1', name: 'Circuit Tracks MIDI', addEventListener: (t, f) => listeners.push(f), removeEventListener() {} };
  const output = { id: 'out1', name: 'Circuit Tracks MIDI', clear() {}, send(d) { const a = Array.from(d); sent.push(a);
    if ((a[0] & 0xF0) === 0xC0) cur[a[0] & 15] = bank[a[1]];
    if (a[0] === 0xF0 && a[6] === 0) cur[a[7]] = a.slice(9, 349);
    if (a[0] === 0xF0 && a[6] === 0x40) { const pl = cur[a[7]] || bank[0]; setTimeout(() => listeners.forEach((f) => f({ data: new Uint8Array([0xF0, 0, 0x20, 0x29, 1, 0x64, 0, a[7], 0, ...pl, 0xF7]) })), 5); } } };
  window.__midiIn = (bytes, ts) => listeners.forEach((f) => f({ data: new Uint8Array(bytes), timeStamp: ts ?? performance.now() }));
  navigator.requestMIDIAccess = async () => ({ inputs: new Map([['in1', input]]), outputs: new Map([['out1', output]]), onstatechange: null });
})();"""
errors = []; results = []
def ok(name, cond, extra=''):
    results.append((name, bool(cond))); print(('PASS ' if cond else 'FAIL ') + name + (' · ' + str(extra) if extra != '' else ''))
